return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'so_SO','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-10-01T06:55:25+00:00','po-revision-date'=>'2026-10-01T06:55:25+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Soo-saaridii aasaaska ahayd ee Page Builder Sandwich oo la dib u dhisay: shaashadda dejinta iyo Ku saabsan, lakabka wax soo saarka hore ee Footprint-Free ah, iyo hal baloog oo tusaale ah.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Zinn Digital® answered, but not with a connection this plugin understands. Nothing was saved.'=>'Zinn Digital® wuu jawaabay, laakin ma ahayn xiriir uu barnaamijkan dheeraadka ahi fahmayo. Waxba lama kaydin.','This site has forgotten its connection. Zinn Digital® could not be told just now, so support staff will see it as unused until it is removed on their side.'=>'Boggan wuxuu ilaaway isku xirkiisa. Zinn Digital® lama ogeysiin karo hadda, markaasna shaqaalaha taageerada ayaa u arki doona inaan la isticmaalin illaa laga saaro dhinacooda.','The Zinn Digital® address this site is set to use is not a secure (https) address, so nothing was sent.'=>'Cinwaanka Zinn Digital® ee uu goobtan u dej sexes inuu isticmaalo ma aha cinwaan ammaan ah (https), markaa waxba lama dirin.','Zinn Digital® could not be reached from this site. Check that the site can make outgoing connections, then try again.'=>'Zinn Digital® lama gaari karo goobtan. Hubi in goobtu sameyn karto xiriirro ka baxaya, kadibna mar kale isku day.','This site\'s connection to Zinn Digital® was revoked. Connect it again to continue.'=>'Xiriirka degelkan ee Zinn Digital® waa la joojiyay. Ku xidh mar kale si aad u sii wadato.','Zinn Digital® no longer recognises this site\'s connection. Connect it again to continue.'=>'Zinn Digital® mar dambe ma aqoonsanayso xiriirka boggan. Dib ugu xir si aad u sii waddo.','Too many requests were sent from this site or address. Wait a little, then try again.'=>'Codsasho aad u badan ayaa laga soo diray boggan ama ciwaankan. In yar sug, kadibna dib u day.','Zinn Digital® could not accept this request. Check the email address and the message, then try again.'=>'Zinn Digital® ma awoodin inay aqbasho codgan. Hubi ciwaanka iimaylka iyo fariinta, kadibna isku day mar kale.','Zinn Digital® could not handle the request just now. Try again in a few minutes.'=>'Zinn Digital® had howkaray codsiga hadda. Mar labaad isku day daqiiqado yar kadib.','The licensing service is not available on this site.'=>'Adeegga shaataynta lagama heli karo boggan.','The trial could not be started here. Continue on the trial page instead.'=>'Imtixaanku lama bilaabi karo halkan. Halkiikeeda ku soco bogga imtixaanka.','Pages saved as standard WordPress blocks'=>'Bogagga lagu kaydiyay xannibaadaha WordPress ee caadiga ah','Sandwich Studio: a full-screen visual editor'=>'Sandwich Studio: tifaftire muuqaal ah oo shaashad buuxda ah','Works inside the normal block editor too'=>'Wuxuu ka shaqeeyaa tifaftiraha baloogga ee caadiga ah sidoo kale','Automatic upgrade of old Page Builder Sandwich pages'=>'Cusboonaysiinta oto-tomatik ah ee bogagga duugga ah ee Page Builder Sandwich','Import from Elementor, Divi, Beaver Builder and WPBakery'=>'Ka soo dhoofiso Elementor, Divi, Beaver Builder iyo WPBakery','Latest WordPress and PHP, tested every release'=>'WordPress iyo PHP-ga ugu dambeeyay, oo la tijaabiyay sii-dayn kasta','Security by design'=>'Amniga oo naqshadeysan','Translated into 58 languages, right-to-left ready'=>'Loo turjumay 5